insert into public.products(id,data) values ('prd-razer-huntsman-v3-pro-tkl','{"slug":"razer-huntsman-v3-pro-tkl","name":"Huntsman V3 Pro TKL","brand":"Razer","categorySlug":"keyboards","price":10995,"compareAtPrice":12995,"rating":4.8,"reviewCount":412,"stock":23,"featured":true,"bestSeller":true,"tags":["analog optical","rapid trigger","tkl","wired"],"shortDescription":"Analog optical switches with adjustable actuation and Rapid Trigger.","description":"The Huntsman V3 Pro TKL brings tournament-grade analog optical switches with per-key adjustable actuation from 0.1mm to 4.0mm. Rapid Trigger resets inputs the instant you let go, giving you the fastest counter-strafes and movement in competitive shooters.","specs":[{"label":"Switches","value":"Razer Analog Optical Gen-2"},{"label":"Form Factor","value":"Tenkeyless (TKL)"},{"label":"Actuation","value":"Adjustable 0.1–4.0mm"},{"label":"Polling Rate","value":"8000 Hz"},{"label":"Connection","value":"USB-C (detachable)"}],"images":["https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#0b6f8f"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-keychron-q1-pro-wireless','{"slug":"keychron-q1-pro-wireless","name":"Q1 Pro Wireless","brand":"Keychron","categorySlug":"keyboards","price":8490,"rating":4.7,"reviewCount":268,"stock":31,"tags":["gasket mount","qmk/via","hot-swap","wireless"],"shortDescription":"Gasket-mounted 75% board with QMK/VIA and triple-mode wireless.","description":"A premium CNC aluminium 75% keyboard with a double-gasket design for a soft, bouncy typing feel. Hot-swappable sockets, full QMK/VIA remapping, and Bluetooth 5.1 across three devices make the Q1 Pro an enthusiast favourite.","specs":[{"label":"Layout","value":"75% (82 keys)"},{"label":"Mount","value":"Double-gasket"},{"label":"Switches","value":"Hot-swap (South-facing)"},{"label":"Software","value":"QMK / VIA"},{"label":"Battery","value":"4000 mAh"}],"images":["https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=900&q=75"],"swatch":["#3ad0ff","#145a74"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-asus-rog-azoth-75','{"slug":"asus-rog-azoth-75","name":"ROG Azoth 75%","brand":"ASUS","categorySlug":"keyboards","price":14995,"rating":4.6,"reviewCount":190,"stock":12,"isNew":true,"tags":["wireless","oled","hot-swap","gasket"],"shortDescription":"Enthusiast 75% wireless board with OLED display and lube kit.","description":"The ROG Azoth fuses gaming performance with enthusiast construction: a gasket-mounted design, pre-lubed ROG NX switches, a 2-inch OLED for stats, and SpeedNova tri-mode wireless rated for 2000 hours.","specs":[{"label":"Layout","value":"75%"},{"label":"Wireless","value":"SpeedNova 2.4GHz / BT / USB-C"},{"label":"Display","value":"2\" OLED"},{"label":"Switches","value":"ROG NX (hot-swap)"},{"label":"Extras","value":"Includes lube kit"}],"images":["https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=900&q=75"],"swatch":["#a855f7","#5a1d8a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-g-pro-x-tkl-lightspeed','{"slug":"logitech-g-pro-x-tkl-lightspeed","name":"G Pro X TKL Lightspeed","brand":"Logitech","categorySlug":"keyboards","price":7290,"compareAtPrice":7990,"rating":4.5,"reviewCount":221,"stock":40,"tags":["wireless","tkl","esports"],"shortDescription":"Compact esports board with Lightspeed wireless and media controls.","description":"Built with and for esports pros, the G Pro X TKL delivers low-latency Lightspeed wireless, swappable GX switches, and a durable aluminium top case in a compact tenkeyless footprint.","specs":[{"label":"Form Factor","value":"TKL"},{"label":"Wireless","value":"Lightspeed 2.4GHz / BT"},{"label":"Switches","value":"GX (Tactile/Linear/Clicky)"},{"label":"Battery","value":"Up to 50 hrs"},{"label":"Media","value":"Dedicated roller + keys"}],"images":["https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#2a3550"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-g-pro-x-superlight-2','{"slug":"logitech-g-pro-x-superlight-2","name":"G Pro X Superlight 2","brand":"Logitech","categorySlug":"mice","price":8290,"rating":4.9,"reviewCount":530,"stock":35,"featured":true,"bestSeller":true,"tags":["wireless","lightweight","hero 2"],"shortDescription":"60g flagship wireless mouse with HERO 2 sensor at 44K DPI.","description":"The Superlight 2 refines the pro-favourite shape at just 60g, now with the HERO 2 sensor (up to 44,000 DPI), hybrid LIGHTFORCE switches, and a 95-hour battery. The choice of more esports champions than any other mouse.","specs":[{"label":"Weight","value":"60 g"},{"label":"Sensor","value":"HERO 2 (44K DPI)"},{"label":"Switches","value":"LIGHTFORCE hybrid"},{"label":"Polling","value":"Up to 8000 Hz"},{"label":"Battery","value":"95 hrs"}],"images":["https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#1b3550"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-viper-v3-pro','{"slug":"razer-viper-v3-pro","name":"Viper V3 Pro","brand":"Razer","categorySlug":"mice","price":8990,"rating":4.8,"reviewCount":377,"stock":28,"isNew":true,"tags":["wireless","54g","ambidextrous"],"shortDescription":"Ultra-light 54g ambidextrous esports mouse, 35K Focus Pro sensor.","description":"Engineered with top FPS pros, the Viper V3 Pro is a 54g symmetrical mouse with the Focus Pro 35K Optical Sensor Gen-2, Gen-3 Optical Switches, and true 8000 Hz HyperPolling wireless out of the box.","specs":[{"label":"Weight","value":"54 g"},{"label":"Sensor","value":"Focus Pro 35K Gen-2"},{"label":"Switches","value":"Optical Gen-3"},{"label":"Polling","value":"8000 Hz"},{"label":"Shape","value":"Ambidextrous"}],"images":["https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=900&q=75"],"swatch":["#b6ff3d","#3a5a12"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-glorious-model-o-2-wireless','{"slug":"glorious-model-o-2-wireless","name":"Model O 2 Wireless","brand":"Glorious","categorySlug":"mice","price":5290,"compareAtPrice":5990,"rating":4.6,"reviewCount":244,"stock":44,"tags":["wireless","honeycomb","lightweight"],"shortDescription":"68g wireless honeycomb mouse with BAMF 2.0 sensor.","description":"The Model O 2 Wireless keeps the beloved vented shell but ditches the cable, landing at 68g with the in-house BAMF 2.0 sensor, optical switches, and up to 110 hours of battery.","specs":[{"label":"Weight","value":"68 g"},{"label":"Sensor","value":"BAMF 2.0 (26K DPI)"},{"label":"Switches","value":"Glorious Optical"},{"label":"Battery","value":"110 hrs"},{"label":"Shape","value":"Ambidextrous"}],"images":["https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=900&q=75"],"swatch":["#a855f7","#3a2a5a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-deathadder-v3','{"slug":"razer-deathadder-v3","name":"DeathAdder V3","brand":"Razer","categorySlug":"mice","price":4790,"rating":4.7,"reviewCount":312,"stock":50,"tags":["wired","ergonomic","59g"],"shortDescription":"Iconic ergonomic shape, now 59g wired with 30K sensor.","description":"The wired DeathAdder V3 refines the legendary ergonomic right-handed shape to a svelte 59g, paired with the Focus Pro 30K sensor and Gen-3 Optical Switches for pure plug-and-play performance.","specs":[{"label":"Weight","value":"59 g"},{"label":"Sensor","value":"Focus Pro 30K"},{"label":"Switches","value":"Optical Gen-3"},{"label":"Cable","value":"Speedflex"},{"label":"Shape","value":"Ergonomic (right)"}],"images":["https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#22304a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-steelseries-arctis-nova-pro-wireless','{"slug":"steelseries-arctis-nova-pro-wireless","name":"Arctis Nova Pro Wireless","brand":"SteelSeries","categorySlug":"headsets","price":17995,"rating":4.8,"reviewCount":356,"stock":15,"featured":true,"tags":["wireless","anc","hot-swap battery"],"shortDescription":"Flagship wireless headset with ANC and dual hot-swap batteries.","description":"The Arctis Nova Pro Wireless pairs a multi-system base station with premium 40mm Neodymium drivers, active noise cancellation, and an infinite power hot-swap battery system so you never stop playing.","specs":[{"label":"Drivers","value":"40mm Neodymium"},{"label":"Wireless","value":"2.4GHz + Bluetooth"},{"label":"ANC","value":"Active, 4-mic hybrid"},{"label":"Battery","value":"Dual hot-swap"},{"label":"Audio","value":"360° Spatial / Hi-Res"}],"images":["https://images.unsplash.com/photo-1599669454699-248893623440?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff3d81","#5a1030"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-hyperx-cloud-iii','{"slug":"hyperx-cloud-iii","name":"Cloud III","brand":"HyperX","categorySlug":"headsets","price":4990,"rating":4.7,"reviewCount":489,"stock":60,"bestSeller":true,"tags":["wired","comfort","memory foam"],"shortDescription":"Legendary comfort with angled 53mm drivers and clear mic.","description":"A refined take on the classic Cloud, the Cloud III brings angled 53mm drivers, DTS Headphone:X spatial audio, and the signature plush memory-foam comfort that made the line iconic.","specs":[{"label":"Drivers","value":"53mm angled"},{"label":"Connection","value":"USB-C / 3.5mm"},{"label":"Mic","value":"10mm detachable"},{"label":"Audio","value":"DTS Headphone:X"},{"label":"Frame","value":"Aluminium"}],"images":["https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1599669454699-248893623440?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff5d95","#4a1228"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-g-pro-x-2-lightspeed','{"slug":"logitech-g-pro-x-2-lightspeed","name":"G Pro X 2 Lightspeed","brand":"Logitech","categorySlug":"headsets","price":11990,"compareAtPrice":12990,"rating":4.6,"reviewCount":201,"stock":22,"tags":["wireless","graphene","esports"],"shortDescription":"Graphene 50mm drivers with tri-mode connectivity.","description":"The G Pro X 2 Lightspeed delivers next-gen 50mm graphene drivers for crisp, distortion-free sound, with Lightspeed wireless, Bluetooth, and a detachable broadcast-grade mic.","specs":[{"label":"Drivers","value":"50mm Graphene"},{"label":"Wireless","value":"Lightspeed + Bluetooth"},{"label":"Battery","value":"Up to 50 hrs"},{"label":"Mic","value":"Detachable, Blue VO!CE"},{"label":"Weight","value":"345 g"}],"images":["https://images.unsplash.com/photo-1599669454699-248893623440?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff3d81","#3a2050"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-blackshark-v2-pro','{"slug":"razer-blackshark-v2-pro","name":"BlackShark V2 Pro","brand":"Razer","categorySlug":"headsets","price":9990,"rating":4.7,"reviewCount":276,"stock":30,"isNew":true,"tags":["wireless","esports","titanium drivers"],"shortDescription":"Esports wireless headset with TriForce Titanium 50mm drivers.","description":"Tuned for competitive clarity, the BlackShark V2 Pro features TriForce Titanium 50mm drivers, a detachable HyperClear Super Wideband mic, and 70-hour battery with low-latency 2.4GHz wireless.","specs":[{"label":"Drivers","value":"TriForce Titanium 50mm"},{"label":"Wireless","value":"HyperSpeed 2.4GHz / BT"},{"label":"Battery","value":"70 hrs"},{"label":"Mic","value":"HyperClear Super Wideband"},{"label":"Weight","value":"320 g"}],"images":["https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1599669454699-248893623440?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff3d81","#2a1540"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-asus-rog-swift-oled-pg27aqdm','{"slug":"asus-rog-swift-oled-pg27aqdm","name":"ROG Swift OLED PG27AQDM","brand":"ASUS","categorySlug":"monitors","price":44995,"rating":4.9,"reviewCount":143,"stock":8,"featured":true,"tags":["oled","240hz","1440p"],"shortDescription":"26.5\" 1440p OLED, 240Hz, 0.03ms with custom heatsink.","description":"A 26.5-inch QD-OLED panel delivering true blacks, 240Hz refresh, and a 0.03ms response time. A custom heatsink and uniform brightness setting keep the panel fast, bright, and protected.","specs":[{"label":"Panel","value":"26.5\" QD-OLED"},{"label":"Resolution","value":"2560 × 1440"},{"label":"Refresh","value":"240 Hz"},{"label":"Response","value":"0.03 ms GtG"},{"label":"HDR","value":"True Black 400"}],"images":["https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=75"],"swatch":["#37e39b","#0d5a40"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-lg-ultragear-27gp850-b','{"slug":"lg-ultragear-27gp850-b","name":"UltraGear 27GP850-B","brand":"LG","categorySlug":"monitors","price":21990,"compareAtPrice":24990,"rating":4.7,"reviewCount":298,"stock":18,"bestSeller":true,"tags":["nano ips","180hz","1440p"],"shortDescription":"27\" Nano IPS 1440p, 165Hz (OC 180Hz), 1ms G-Sync.","description":"A long-time value champion: a 27-inch Nano IPS QHD panel with 165Hz (overclockable to 180Hz), 1ms GtG response, and G-Sync Compatible / FreeSync Premium support.","specs":[{"label":"Panel","value":"27\" Nano IPS"},{"label":"Resolution","value":"2560 × 1440"},{"label":"Refresh","value":"165 Hz (OC 180)"},{"label":"Response","value":"1 ms GtG"},{"label":"Sync","value":"G-Sync / FreeSync Premium"}],"images":["https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=900&q=75"],"swatch":["#37e39b","#124a5a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-samsung-odyssey-g7-32','{"slug":"samsung-odyssey-g7-32","name":"Odyssey G7 32\"","brand":"Samsung","categorySlug":"monitors","price":28990,"rating":4.5,"reviewCount":176,"stock":11,"tags":["va","240hz","1000r curve"],"shortDescription":"32\" 1440p VA, 240Hz, aggressive 1000R curve.","description":"The Odyssey G7 wraps a 32-inch QHD VA panel into a dramatic 1000R curve matched to the eye, pushing 240Hz and 1ms response with HDR600 for deep immersion.","specs":[{"label":"Panel","value":"32\" VA 1000R"},{"label":"Resolution","value":"2560 × 1440"},{"label":"Refresh","value":"240 Hz"},{"label":"Response","value":"1 ms"},{"label":"HDR","value":"HDR600"}],"images":["https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=75"],"swatch":["#2ce0b0","#0d4a52"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-benq-zowie-xl2566k','{"slug":"benq-zowie-xl2566k","name":"ZOWIE XL2566K","brand":"BenQ","categorySlug":"monitors","price":32990,"rating":4.8,"reviewCount":121,"stock":9,"isNew":true,"tags":["360hz","dyac+","esports"],"shortDescription":"24.5\" 1080p 360Hz esports monitor with DyAc+.","description":"The gold standard for competitive CS and Valorant: a 24.5-inch 1080p TN-class panel at a blistering 360Hz with DyAc+ motion clarity, S-Switch, and adjustable Shield.","specs":[{"label":"Panel","value":"24.5\" Fast panel"},{"label":"Resolution","value":"1920 × 1080"},{"label":"Refresh","value":"360 Hz"},{"label":"Tech","value":"DyAc+ motion blur reduction"},{"label":"Extras","value":"S-Switch + Shield"}],"images":["https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=900&q=75"],"swatch":["#37e39b","#0d4a3a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-artisan-zero-xl-soft','{"slug":"artisan-zero-xl-soft","name":"Zero XL Soft","brand":"Artisan","categorySlug":"mousepads","price":2890,"rating":4.9,"reviewCount":158,"stock":26,"featured":true,"tags":["control","japanese","xl"],"shortDescription":"Premium Japanese control surface with balanced glide.","description":"Handcrafted in Japan, the Artisan Zero offers a refined control-oriented surface with a consistent stop and a smooth initial glide, finished with a grippy rubber base.","specs":[{"label":"Size","value":"490 × 420 mm (XL)"},{"label":"Type","value":"Control (Mid)"},{"label":"Surface","value":"Textured cloth"},{"label":"Base","value":"Rubber anti-slip"},{"label":"Thickness","value":"4 mm"}],"images":["https://images.unsplash.com/photo-1616763355548-1b606f439f86?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=900&q=75"],"swatch":["#ffb547","#5a3a0d"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-g840-xl','{"slug":"logitech-g840-xl","name":"G840 XL","brand":"Logitech","categorySlug":"mousepads","price":1990,"compareAtPrice":2490,"rating":4.7,"reviewCount":402,"stock":70,"bestSeller":true,"tags":["cloth","xl","value"],"shortDescription":"Large cloth desk pad tuned for Logitech sensors.","description":"A spacious XL cloth gaming surface optimised for high and low DPI tracking, with a stable rubber base and a consistent moderate-friction weave.","specs":[{"label":"Size","value":"900 × 400 mm (XL)"},{"label":"Type","value":"Speed/Control balance"},{"label":"Surface","value":"Cloth"},{"label":"Base","value":"Rubber"},{"label":"Thickness","value":"3 mm"}],"images":["https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1616763355548-1b606f439f86?auto=format&fit=crop&w=900&q=75"],"swatch":["#ffc766","#4a3310"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-glorious-3xl-stealth','{"slug":"glorious-3xl-stealth","name":"3XL Stealth","brand":"Glorious","categorySlug":"mousepads","price":2290,"rating":4.6,"reviewCount":189,"stock":33,"tags":["desk mat","stitched","3xl"],"shortDescription":"Full-desk mat with stitched edges and fast-glide cloth.","description":"Cover your entire setup with the 3XL Stealth desk mat, featuring a machine-washable cloth surface, stitched anti-fray edges, and a thick non-slip base.","specs":[{"label":"Size","value":"1220 × 610 mm (3XL)"},{"label":"Type","value":"Speed"},{"label":"Edges","value":"Stitched"},{"label":"Base","value":"Natural rubber"},{"label":"Thickness","value":"3 mm"}],"images":["https://images.unsplash.com/photo-1616763355548-1b606f439f86?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=900&q=75"],"swatch":["#ffb547","#3a2a0d"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-strider-hybrid-xxl','{"slug":"razer-strider-hybrid-xxl","name":"Strider Hybrid XXL","brand":"Razer","categorySlug":"mousepads","price":2690,"rating":4.7,"reviewCount":134,"stock":29,"isNew":true,"tags":["hybrid","hard-soft","xxl"],"shortDescription":"Hard-soft hybrid surface: control feel, speed glide.","description":"The Strider Hybrid blends the fast, frictionless glide of a hard pad with the controlled stops of a soft mat, wrapped in a spill-resistant coating over an anti-slip base.","specs":[{"label":"Size","value":"940 × 410 mm (XXL)"},{"label":"Type","value":"Hybrid hard/soft"},{"label":"Surface","value":"Micro-textured"},{"label":"Coating","value":"Water-resistant"},{"label":"Base","value":"Anti-slip"}],"images":["https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1616763355548-1b606f439f86?auto=format&fit=crop&w=900&q=75"],"swatch":["#ffbe5a","#3a2416"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-xbox-elite-series-2','{"slug":"xbox-elite-series-2","name":"Elite Series 2","brand":"Xbox","categorySlug":"controllers","price":9990,"rating":4.6,"reviewCount":421,"stock":24,"featured":true,"tags":["pro","paddles","wireless"],"shortDescription":"Pro controller with adjustable tension and 4 paddles.","description":"The Elite Series 2 offers adjustable-tension thumbsticks, interchangeable components, four back paddles, hair-trigger locks, and up to 40 hours of rechargeable battery for PC and Xbox.","specs":[{"label":"Connection","value":"Wireless / BT / USB-C"},{"label":"Paddles","value":"4 removable"},{"label":"Sticks","value":"Adjustable tension"},{"label":"Battery","value":"Up to 40 hrs"},{"label":"Profiles","value":"3 on-board + default"}],"images":["https://images.unsplash.com/photo-1592840496694-26d035b52b48?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1600080972464-8e5f35f63d08?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#14323f"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-8bitdo-ultimate-wireless-controller','{"slug":"8bitdo-ultimate-wireless-controller","name":"Ultimate Wireless Controller","brand":"8BitDo","categorySlug":"controllers","price":3490,"rating":4.8,"reviewCount":367,"stock":55,"bestSeller":true,"tags":["hall-effect","dock","value"],"shortDescription":"Hall-effect sticks, charging dock, and deep remapping.","description":"A remarkable value: Hall-effect joysticks that never drift, a charging dock in the box, back buttons, and full remapping via the 8BitDo Ultimate Software for PC and Switch.","specs":[{"label":"Sticks","value":"Hall-effect"},{"label":"Connection","value":"2.4GHz / BT / Wired"},{"label":"Extras","value":"Charging dock"},{"label":"Buttons","value":"2 back + L4/R4"},{"label":"Battery","value":"Up to 22 hrs"}],"images":["https://images.unsplash.com/photo-1600080972464-8e5f35f63d08?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1592840496694-26d035b52b48?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#2a3550"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-sony-dualsense-edge','{"slug":"sony-dualsense-edge","name":"DualSense Edge","brand":"Sony","categorySlug":"controllers","price":11990,"rating":4.5,"reviewCount":212,"stock":17,"isNew":true,"tags":["haptics","adaptive triggers","pro"],"shortDescription":"Pro DualSense with swappable sticks and back buttons.","description":"The DualSense Edge adds pro features to Sony''s acclaimed pad: replaceable stick modules, remappable back buttons, adjustable trigger travel, and on-the-fly profile switching — plus signature haptics.","specs":[{"label":"Haptics","value":"Adaptive triggers + haptics"},{"label":"Sticks","value":"Replaceable modules"},{"label":"Buttons","value":"Back buttons (2 types)"},{"label":"Triggers","value":"Adjustable travel"},{"label":"Connection","value":"USB-C / Wireless"}],"images":["https://images.unsplash.com/photo-1592840496694-26d035b52b48?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1600080972464-8e5f35f63d08?auto=format&fit=crop&w=900&q=75"],"swatch":["#6ba8ff","#1b2f55"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-wolverine-v2-pro','{"slug":"razer-wolverine-v2-pro","name":"Wolverine V2 Pro","brand":"Razer","categorySlug":"controllers","price":14990,"rating":4.4,"reviewCount":98,"stock":13,"tags":["wireless","mecha-tactile","pc/ps5"],"shortDescription":"Wireless pro pad with mecha-tactile buttons and mouse-click bumpers.","description":"Tuned for competitive play on PC and PS5, the Wolverine V2 Pro features mecha-tactile action buttons, a HyperSpeed wireless connection, six remappable multi-function buttons, and interchangeable sticks.","specs":[{"label":"Buttons","value":"Mecha-tactile"},{"label":"Connection","value":"HyperSpeed Wireless / USB-C"},{"label":"Remap","value":"6 multi-function"},{"label":"Sticks","value":"Interchangeable caps"},{"label":"Platforms","value":"PC / PS5"}],"images":["https://images.unsplash.com/photo-1600080972464-8e5f35f63d08?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1592840496694-26d035b52b48?auto=format&fit=crop&w=900&q=75"],"swatch":["#27e6ff","#2a1540"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-shure-sm7b','{"slug":"shure-sm7b","name":"SM7B","brand":"Shure","categorySlug":"microphones","price":24990,"rating":4.9,"reviewCount":287,"stock":14,"featured":true,"tags":["xlr","dynamic","broadcast"],"shortDescription":"Legendary broadcast dynamic mic for voice and streaming.","description":"The industry-standard SM7B is a cardioid dynamic microphone with a flat, wide-range frequency response, superb background rejection, and built-in pop filtering — the voice of countless studios and streamers.","specs":[{"label":"Type","value":"Dynamic (XLR)"},{"label":"Pattern","value":"Cardioid"},{"label":"Response","value":"50 Hz – 20 kHz"},{"label":"Filtering","value":"Bass roll-off + presence"},{"label":"Shielding","value":"Hum-rejecting"}],"images":["https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=900&q=75"],"swatch":["#a855f7","#2a1b3a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-elgato-wave-3','{"slug":"elgato-wave-3","name":"Wave:3","brand":"Elgato","categorySlug":"microphones","price":8490,"rating":4.7,"reviewCount":319,"stock":38,"bestSeller":true,"tags":["usb","condenser","streaming"],"shortDescription":"USB condenser with Clipguard and Wave Link mixing.","description":"A premium USB condenser built for streamers: a cardioid capsule with 24-bit/96kHz capture, proprietary Clipguard anti-distortion, capacitive mute, and the powerful Wave Link app for software mixing.","specs":[{"label":"Type","value":"Condenser (USB-C)"},{"label":"Pattern","value":"Cardioid"},{"label":"Sampling","value":"24-bit / 96 kHz"},{"label":"Tech","value":"Clipguard anti-clip"},{"label":"Software","value":"Wave Link mixer"}],"images":["https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=900&q=75"],"swatch":["#b06cff","#2a1b4a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-hyperx-quadcast-s','{"slug":"hyperx-quadcast-s","name":"QuadCast S","brand":"HyperX","categorySlug":"microphones","price":7990,"compareAtPrice":8990,"rating":4.6,"reviewCount":356,"stock":41,"tags":["usb","rgb","4 patterns"],"shortDescription":"RGB USB condenser with four polar patterns and tap-to-mute.","description":"The QuadCast S combines striking RGB lighting with genuine versatility: four selectable polar patterns, a built-in anti-vibration shock mount, tap-to-mute sensor, and gain control dial.","specs":[{"label":"Type","value":"Condenser (USB-C)"},{"label":"Patterns","value":"4 (cardioid/omni/bi/stereo)"},{"label":"Mount","value":"Built-in shock mount"},{"label":"Controls","value":"Tap-mute + gain dial"},{"label":"Lighting","value":"Dynamic RGB"}],"images":["https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=900&q=75"],"swatch":["#a855f7","#3a1b2a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-blue-yeti-x','{"slug":"blue-yeti-x","name":"Yeti X","brand":"Blue","categorySlug":"microphones","price":9490,"rating":4.5,"reviewCount":263,"stock":27,"isNew":true,"tags":["usb","metering","4 patterns"],"shortDescription":"Pro USB mic with LED metering and smart knob.","description":"The Yeti X delivers a four-capsule array with four pickup patterns, a high-resolution LED meter for monitoring your levels at a glance, and a multifunction smart knob with Blue VO!CE effects.","specs":[{"label":"Type","value":"Condenser (USB)"},{"label":"Capsules","value":"4-capsule array"},{"label":"Patterns","value":"4 selectable"},{"label":"Metering","value":"11-segment LED"},{"label":"Effects","value":"Blue VO!CE"}],"images":["https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=900&q=75"],"swatch":["#9b5cff","#241b4a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-elgato-facecam-mk-2','{"slug":"elgato-facecam-mk-2","name":"Facecam MK.2","brand":"Elgato","categorySlug":"webcams","price":8990,"rating":4.6,"reviewCount":177,"stock":32,"featured":true,"tags":["1080p60","streaming","sony sensor"],"shortDescription":"1080p60 streaming cam with Sony sensor and HDR.","description":"The Facecam MK.2 captures sharp, true-to-life 1080p60 video with a Sony STARVIS sensor, an all-glass lens, onboard HDR, and deep control via Camera Hub — purpose-built for streaming.","specs":[{"label":"Resolution","value":"1080p60"},{"label":"Sensor","value":"Sony STARVIS"},{"label":"Lens","value":"All-glass, f/2.0"},{"label":"HDR","value":"Yes"},{"label":"FOV","value":"Adjustable 74–82°"}],"images":["https://images.unsplash.com/photo-1500726726099-3f759a2eaa99?auto=format&fit=crop&w=900&q=75"],"swatch":["#37e39b","#0d4a3a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-brio-4k','{"slug":"logitech-brio-4k","name":"Brio 4K","brand":"Logitech","categorySlug":"webcams","price":11990,"rating":4.5,"reviewCount":401,"stock":21,"bestSeller":true,"tags":["4k","hdr","windows hello"],"shortDescription":"4K Ultra HD webcam with HDR and Windows Hello.","description":"The Brio 4K delivers Ultra HD video with RightLight 3 and HDR for low-light scenes, 5x digital zoom, multiple fields of view, and IR support for Windows Hello face login.","specs":[{"label":"Resolution","value":"4K UHD / 1080p60"},{"label":"HDR","value":"RightLight 3 + HDR"},{"label":"Zoom","value":"5x digital"},{"label":"FOV","value":"65 / 78 / 90°"},{"label":"Login","value":"Windows Hello (IR)"}],"images":["https://images.unsplash.com/photo-1500726726099-3f759a2eaa99?auto=format&fit=crop&w=900&q=75"],"swatch":["#2ce0b0","#124a52"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-kiyo-pro','{"slug":"razer-kiyo-pro","name":"Kiyo Pro","brand":"Razer","categorySlug":"webcams","price":9490,"compareAtPrice":10990,"rating":4.4,"reviewCount":188,"stock":19,"tags":["1080p60","hdr","adaptive light"],"shortDescription":"1080p60 webcam with adaptive light sensor and HDR.","description":"The Kiyo Pro uses a large adaptive light sensor to stay crisp in dim rooms, shoots uncompressed 1080p60, supports HDR at 30fps, and offers a wide, distortion-corrected field of view.","specs":[{"label":"Resolution","value":"1080p60 (uncompressed)"},{"label":"Sensor","value":"Adaptive light (STARVIS)"},{"label":"HDR","value":"1080p30"},{"label":"Lens","value":"Wide, distortion-free"},{"label":"Connection","value":"USB 3.0"}],"images":["https://images.unsplash.com/photo-1500726726099-3f759a2eaa99?auto=format&fit=crop&w=900&q=75"],"swatch":["#37e39b","#0d3a4a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-c920-hd-pro','{"slug":"logitech-c920-hd-pro","name":"C920 HD Pro","brand":"Logitech","categorySlug":"webcams","price":3990,"rating":4.6,"reviewCount":712,"stock":64,"tags":["1080p30","value","stereo mic"],"shortDescription":"The dependable 1080p work-and-stream classic.","description":"A perennial best-seller, the C920 shoots clean 1080p30 with automatic light correction and dual stereo mics — the no-fuss choice for calls, class, and casual streaming.","specs":[{"label":"Resolution","value":"1080p30"},{"label":"Lens","value":"Glass, autofocus"},{"label":"Mic","value":"Dual stereo"},{"label":"FOV","value":"78°"},{"label":"Connection","value":"USB-A"}],"images":["https://images.unsplash.com/photo-1500726726099-3f759a2eaa99?auto=format&fit=crop&w=900&q=75"],"swatch":["#2ce0b0","#17323f"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-secretlab-titan-evo-2024','{"slug":"secretlab-titan-evo-2024","name":"Titan Evo 2024","brand":"Secretlab","categorySlug":"chairs","price":24990,"rating":4.8,"reviewCount":523,"stock":16,"featured":true,"bestSeller":true,"tags":["ergonomic","lumbar","neo hybrid"],"shortDescription":"Flagship ergonomic chair with integrated adaptive lumbar.","description":"The Titan Evo sets the standard for gaming chairs with an integrated 4-way L-ADAPT lumbar support, a pebble-seat base for even weight distribution, magnetic head pillow, and durable NEO Hybrid Leatherette.","specs":[{"label":"Lumbar","value":"4-way L-ADAPT integrated"},{"label":"Upholstery","value":"NEO Hybrid Leatherette"},{"label":"Armrests","value":"4D CloudSwap"},{"label":"Recline","value":"Up to 165°"},{"label":"Capacity","value":"Up to 130 kg"}],"images":["https://images.unsplash.com/photo-1592078615290-033ee584e267?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff3d81","#4a1028"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-razer-iskur-v2','{"slug":"razer-iskur-v2","name":"Iskur V2","brand":"Razer","categorySlug":"chairs","price":22990,"rating":4.6,"reviewCount":214,"stock":12,"isNew":true,"tags":["lumbar arch","ergonomic","6d armrests"],"shortDescription":"Adjustable lumbar-arch chair with reactive support.","description":"The Iskur V2 features a fully adjustable built-in lumbar arch that flexes with your spine, 6D armrests, a dense-foam seat, and multi-layer synthetic leather for long sessions.","specs":[{"label":"Lumbar","value":"Adjustable arch (reactive)"},{"label":"Armrests","value":"6D"},{"label":"Upholstery","value":"Multi-layer synthetic"},{"label":"Recline","value":"Up to 152°"},{"label":"Capacity","value":"Up to 136 kg"}],"images":["https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1592078615290-033ee584e267?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff3d81","#2a1030"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-logitech-g-x-herman-miller-embody-gaming','{"slug":"logitech-g-x-herman-miller-embody-gaming","name":"Embody Gaming","brand":"Logitech G x Herman Miller","categorySlug":"chairs","price":69990,"rating":4.9,"reviewCount":87,"stock":5,"tags":["premium","posture","12-year warranty"],"shortDescription":"Co-engineered posture-support chair for gamers.","description":"A collaboration between Herman Miller and Logitech G, the Embody Gaming chair uses a pixelated support system and copper-infused cooling foam to promote healthy posture and circulation during marathon sessions.","specs":[{"label":"Support","value":"Pixelated BackFit"},{"label":"Cooling","value":"Copper-infused foam"},{"label":"Armrests","value":"Fully adjustable"},{"label":"Warranty","value":"12 years"},{"label":"Tilt","value":"Backfit adjustment"}],"images":["https://images.unsplash.com/photo-1592078615290-033ee584e267?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff5d95","#3a1a2a"]}'::jsonb) on conflict do nothing;
insert into public.products(id,data) values ('prd-corsair-tc100-relaxed','{"slug":"corsair-tc100-relaxed","name":"TC100 Relaxed","brand":"Corsair","categorySlug":"chairs","price":12990,"compareAtPrice":14990,"rating":4.4,"reviewCount":269,"stock":23,"tags":["value","ergonomic","wide seat"],"shortDescription":"Comfort-focused chair with wide seat and breathable fabric.","description":"The TC100 Relaxed pairs a spacious, flat seat with a tall backrest, soft breathable cloth (or leatherette), and smooth 4D armrests for relaxed all-day comfort at a friendly price.","specs":[{"label":"Seat","value":"Wide flat base"},{"label":"Upholstery","value":"Breathable fabric"},{"label":"Armrests","value":"4D"},{"label":"Recline","value":"Up to 180°"},{"label":"Capacity","value":"Up to 120 kg"}],"images":["https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=75","https://images.unsplash.com/photo-1592078615290-033ee584e267?auto=format&fit=crop&w=900&q=75"],"swatch":["#ff8fb0","#3a1a26"]}'::jsonb) on conflict do nothing;
